import {retainedRows,checkshotQC,surveySupport} from './well-derived.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function openWellQC(host,dataset){
 const scope=host.getProject().id,source=await retainedRows(host,dataset,50000);if(host.getProject()?.id!==scope)return;let page=0,qc=[],notice='';
 if(dataset.family==='checkshots')try{const support=dataset.references?.depthReference==='MD'?surveySupport(host,dataset.well,host.getState().ingestion?.datasets||[]):null;if(support?.loading)await support.promise;qc=checkshotQC(dataset,source.rows,dataset.references?.verticalDatum&&dataset.references.verticalDatum===support?.references.verticalDatum?support?.stations||[]:[]);if(support?.error)notice=support.error;}catch(e){notice=e.message;}
 function plot(name,x,y,xLabel,yLabel){const pairs=qc.filter(r=>Number.isFinite(r[x])&&Number.isFinite(r[y]));if(pairs.length<2)return '';const xmin=Math.min(...pairs.map(p=>p[x])),xmax=Math.max(...pairs.map(p=>p[x])),ymin=Math.min(...pairs.map(p=>p[y])),ymax=Math.max(...pairs.map(p=>p[y]));if(xmin===xmax||ymin===ymax)return '';const stride=Math.max(1,Math.ceil(pairs.length/4000));return `<figure class="well-qc-plot"><figcaption>${esc(name)}</figcaption><svg viewBox="0 0 600 280" role="img" aria-label="${esc(name)}"><path d="M55 20V245H580" fill="none" stroke="#9caeaa"/>${pairs.filter((_,i)=>i%stride===0).map(p=>`<circle cx="${55+(p[x]-xmin)/(xmax-xmin)*520}" cy="${20+(p[y]-ymin)/(ymax-ymin)*225}" r="1.5" fill="#087c73"/>`).join('')}<text x="55" y="270">${esc(xLabel)} · ${xmin.toPrecision(4)} … ${xmax.toPrecision(4)}</text><text x="5" y="14">${esc(yLabel)} · ${ymin.toPrecision(4)} … ${ymax.toPrecision(4)}</text></svg><small>Actual valid observations · at most 4,000 drawn points; table retains all ${qc.length} records.</small></figure>`;}
 function draw(){const refs=dataset.references||{},well=host.getState().wellDrafts?.find(w=>w.id===dataset.well);host.modal('Well evidence · '+esc(dataset.name),`<p>${esc(well?.name||dataset.well||'Unassigned')} · ${esc(refs.depthReference||'Unconfirmed depth')} · ${esc(refs.verticalDatum||'Elevation datum unresolved')} · ${esc(refs.timeDatum||'Time datum unresolved')}</p><p class="sub">Original observations and derived QC are separate. This view does not grant scientific approval.</p>${notice?`<p class="note">${esc(notice)}</p>`:''}${qc.length?`<div class="well-qc-grid">${plot('Time–depth observations','time','depth','Time (s)',qc.some(r=>r.derivedDepth)?'Derived TVD (m)':'Source '+(refs.depthReference||'depth')+' (m)')}${plot('Derived interval velocity','velocity','depth','Interval velocity (m/s)',qc.some(r=>r.derivedDepth)?'Derived TVD (m)':'Source '+(refs.depthReference||'depth')+' (m)')}</div>`:''}<div class="actions"><button id="well-qc-prev" ${page===0?'disabled':''}>Previous</button><span>Records ${page*250+1}–${Math.min((page+1)*250,source.rows.length)} of ${source.rows.length}</span><button id="well-qc-next" ${(page+1)*250>=source.rows.length?'disabled':''}>Next</button><button id="well-qc-csv">Export complete observations and QC</button>${well&&dataset.family==='checkshots'?`<button id="well-qc-active" ${well.activeCheckshotId===dataset.id?'disabled':''}>${well.activeCheckshotId===dataset.id?'Active checkshot':'Set as active checkshot'}</button>`:''}</div><div class="table-wrap wi-preview"><table><thead><tr><th>Source row</th>${source.columns.map(c=>`<th>${esc(c.mnemonic)}<small>${esc(c.effectiveUnit||c.unit)}</small></th>`).join('')}${qc.length?'<th>QC depth (m)</th><th>Derived interval velocity (m/s)</th><th>QC note</th>':''}</tr></thead><tbody>${source.rows.slice(page*250,(page+1)*250).map((row,i)=>`<tr><td>${page*250+i+1}</td>${row.map(v=>`<td>${esc(v)}</td>`).join('')}${qc.length?`<td>${qc[page*250+i].depth} ${qc[page*250+i].derivedDepth?'(derived TVD)':''}</td><td>${qc[page*250+i].velocity?.toPrecision(7)||'—'}</td><td>${esc(qc[page*250+i].issue)}</td>`:''}</tr>`).join('')}</tbody></table></div>`);
  document.querySelector('#well-qc-prev').onclick=()=>{page--;draw();};document.querySelector('#well-qc-next').onclick=()=>{page++;draw();};document.querySelector('#well-qc-active')?.addEventListener('click',async()=>{well.activeCheckshotId=dataset.id;host.save();await host.flush();draw();});document.querySelector('#well-qc-csv').onclick=()=>{const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"',header=[...source.columns.map(c=>c.mnemonic),...(qc.length?['QC depth (m)','Depth derived from active survey','Derived interval velocity (m/s)','QC note']:[])];host.download(dataset.name+'.qc.csv',new Blob([[header,...source.rows.map((row,i)=>[...row,...(qc.length?[qc[i].depth,qc[i].derivedDepth,qc[i].velocity,qc[i].issue]:[])])].map(row=>row.map(cell).join(',')).join('\n')],{type:'text/csv'}));};
 }draw();
}
